scripts.lcg_generator:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    for _ in range(k):
        s = (a * s + b) % m

    return float(s)

scripts.modular_exponent:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']

    result = pow(base, exp, mod)
    return float(result)

scripts.sum_values:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
